INSERT INTO public.blog_posts (
  slug, title, excerpt, content, category, author_name, read_time,
  featured, tags, keywords, faqs, videos,
  seo_title, seo_description, focus_keyword, branded_cta, status, published_at
)
SELECT
  s.slug, s.title, s.excerpt, s.content, s.category, s.author_name, s.read_time,
  s.featured, s.tags, s.keywords, s.faqs, s.videos,
  s.seo_title, s.seo_description, s.focus_keyword, s.branded_cta, 'published', s.published_at
FROM jsonb_to_recordset($blogseed$[{"slug":"how-to-write-youtube-titles-that-get-clicks-2026","title":"How to Write YouTube Titles That Get Clicks (7 Proven Formulas)","excerpt":"Your title is half your packaging. Length rules, 7 formulas that keep working, the mistakes that kill CTR, and how to A/B test titles in YouTube Studio.","content":"\n> **How do you write YouTube titles that get clicks?** Good YouTube titles make one specific promise, put the most important words in the first 50 or so characters, and work together with the thumbnail instead of repeating it. Write three to five candidates per video, then let YouTube's built-in A/B test pick the winner by watch time rather than trusting your gut.\n\n![How to write YouTube titles that get clicks: title variations in Creator AI's ideation tool](/ideation%20page.png)\n\nMost creators spend six hours on a video and six minutes on its title. That ratio is backwards. The title and thumbnail are the only parts of your video a stranger sees before deciding whether to give you their time, and the algorithm only shows your work to more people when those strangers click and then stay.\n\nThis guide covers how to write YouTube titles that earn the click honestly: the length rules, seven formulas that keep working, the mistakes that quietly kill click-through rate, and how to test titles instead of guessing.\n\n## Why YouTube titles matter more than you think\n\nYouTube titles are half of your packaging, and packaging decides whether a video gets a chance at all. YouTube's own [thumbnail and title tips](https://support.google.com/youtube/answer/12340300) frame the two as a pair: the thumbnail grabs attention, the title tells the viewer what they will get.\n\nClick-through rate on its own is not the goal, though. YouTube rewards videos that viewers click *and* are satisfied by. A clickbait title that wins the click but loses the viewer in 20 seconds teaches the system that your video disappoints people. We covered that trade-off in depth in [what the YouTube algorithm actually rewards for small channels](/blog/youtube-algorithm-for-small-channels-what-it-actually-rewards-2026).\n\nSo the job of a title is narrow and precise: attract the right viewer, and set an expectation the video then keeps.\n\n## The hard limits: length and truncation\n\nYouTube allows titles up to 100 characters, according to [YouTube Help](https://support.google.com/youtube/answer/57407). That is the ceiling, not the target.\n\nWhat viewers actually see is shorter. Titles get cut off on mobile home feeds, in suggested video sidebars, and in search results, and the exact cutoff varies by device and layout. The practical rule:\n\n- **Front-load the promise.** The words that make someone click should sit in the first 40 to 50 characters.\n- **Treat the rest as a bonus.** Anything after that should be safe to lose.\n- **Check it on a phone.** Most YouTube viewing happens on mobile, so preview your title there before publishing.\n\n| Title | Problem | Fix |\n|---|---|---|\n| My Honest Thoughts After Using This Camera for a Year (Sony ZV-E10) | The product name, the reason to click, is at the end and gets cut | Sony ZV-E10 After 1 Year: My Honest Review |\n| Episode 47: Talking About Budgeting | Says nothing a stranger cares about | I Tracked Every Dollar for 30 Days (Here's What Changed) |\n\n## 7 formulas for YouTube titles that keep working\n\nFormulas are not a shortcut around having an interesting video. They are a way to describe an interesting video clearly. These seven show up again and again across niches.\n\n### 1. The specific result\n\n*\"I Grew a Channel From 0 to 10,000 Subscribers in 9 Months.\"* Specific numbers read as true. Vague ones (\"fast\", \"a lot\") read as marketing.\n\n### 2. The how-to with a constraint\n\n*\"How to Edit a YouTube Video on Your Phone (No Paid Apps).\"* The constraint filters for exactly the viewer the video serves.\n\n### 3. The mistake or warning\n\n*\"Stop Doing This in Your First 10 Seconds.\"* Negative framing works because avoiding loss motivates people more than chasing gain. Use it only when the video genuinely names the mistake.\n\n### 4. The comparison\n\n*\"Canva vs VEED: Which Editor Fits YouTube in 2026?\"* Comparison viewers are close to a decision, so these titles attract high-intent traffic. See our [Canva vs VEED breakdown](/blog/canva-vs-veed-which-browser-video-editor-fits-youtube-2026) for how that plays out.\n\n### 5. The curiosity gap\n\n*\"The Setting Every Beginner Gets Wrong.\"* A curiosity gap opens a question the viewer wants closed. It must be closed early in the video, or retention collapses.\n\n### 6. The list\n\n*\"5 Budget Mics That Sound Expensive.\"* Lists promise a clear structure and an end point, which lowers the commitment of clicking.\n\n### 7. The personal experiment\n\n*\"I Tried Posting Every Day for 30 Days.\"* Experiment titles combine a story, a timeframe and an implied result in one line.\n\n## How YouTube titles and thumbnails should work together\n\nThe most common packaging mistake is a thumbnail that repeats the title word for word. That wastes half your space.\n\nTreat them as two halves of one sentence. The thumbnail shows the emotion or the visual hook; the title adds the context. A thumbnail of a burnt cake with the text \"WHY?\" paired with the title *\"I Followed a Viral Recipe Exactly (It Failed)\"* works because each piece adds something the other lacks.\n\nIf you are designing the thumbnail side, our guide to [thumbnail mistakes that kill your CTR](/blog/youtube-thumbnail-mistakes-killing-your-ctr-2026) covers the visual half of this pairing.\n\n## Mistakes that quietly kill YouTube titles\n\n### Writing for the algorithm instead of the viewer\n\nStuffing keywords into YouTube titles (\"Budget Travel Tips Cheap Travel Travel Hacks 2026\") reads as spam to humans. Search matching is far smarter than exact keywords now. Write one natural phrase that includes what people search for, then stop.\n\n### Promising more than the video delivers\n\nIf the title says \"I Quit My Job\" and the video is about considering quitting, viewers leave and some leave angry. The short-term click costs you long-term trust and retention.\n\n### Being clever instead of clear\n\nInside jokes and puns only land with people who already know you. Strangers, the people you need to grow, scroll past a title they cannot decode in a second.\n\n### Changing titles too often\n\nRewriting a title every few hours makes it impossible to tell what worked. Use a proper test instead.\n\n## Test your YouTube titles instead of guessing\n\nYouTube Studio now lets you A/B test titles as well as thumbnails. According to [YouTube Help](https://support.google.com/youtube/answer/16391400), you can test up to three titles, up to three thumbnails, or combinations of both. The version with the highest watch time is then shown to all viewers.\n\nThat last detail matters. The winner is chosen by watch time, not raw clicks, which is YouTube quietly enforcing the rule from the top of this post: a title has to earn the click *and* keep the viewer.\n\nA few limits worth knowing from the same help page:\n\n- It runs on desktop YouTube Studio only, and needs advanced features enabled.\n- Shorts, scheduled lives and Premieres cannot be tested yet.\n- Made for kids, mature and private videos are excluded.\n\nA simple routine: write five YouTube titles for every video, cut to your best three, and run them as a test on every long-form upload. After ten videos you will have real data on which formulas work for your audience, which is worth more than any list of formulas, including this one.\n\n## Where Creator AI fits in\n\nComing up with five genuinely different title candidates is the hard part, because your first idea anchors every idea after it.\n\nCreator AI's ideation tool helps here. Each video idea it returns comes with several title variations alongside an opportunity score, drawn from trend signals in your niche. If you have trained AI Studio on your channel, the suggestions follow your voice rather than generic clickbait. You still choose, and you still test, but you start from a spread of options instead of one.\n\nFor the next step after the title, our guide on [writing YouTube hooks that stop the scroll](/blog/how-to-write-youtube-hooks-that-stop-the-scroll) covers how to keep the promise your title just made in the first 15 seconds. And if you are still hunting for what to make, start with our [YouTube video ideation system](/blog/youtube-video-ideation-system-for-youtube-creators-2026).\n\n## Conclusion\n\nGreat YouTube titles are not tricks. They are clear, specific promises, front-loaded for mobile, paired with a thumbnail that adds rather than repeats, and tested by watch time rather than instinct.\n\nWrite more candidates than feels necessary, keep the promise in the first minute of the video, and let YouTube's own A/B test settle the argument. Do that on every upload and your YouTube titles will improve faster than any formula could make them.\n","category":"Growth","author_name":"Afrin Nahar","read_time":"8 min read","featured":false,"tags":["YouTube Titles","CTR","Packaging","Growth"],"keywords":["how to write youtube titles","youtube title formulas","youtube title length limit","youtube title a/b testing","clickbait vs good youtube titles","youtube title and thumbnail together"],"faqs":[{"question":"How long should YouTube titles be?","answer":"YouTube allows up to 100 characters, but titles get truncated on mobile and in suggestions. Put the words that make someone click in the first 40 to 50 characters and treat the rest as optional."},{"question":"Can you A/B test YouTube titles?","answer":"Yes. YouTube Studio on desktop lets you test up to three titles, thumbnails, or combinations. The version with the highest watch time is then shown to all viewers. Shorts, Premieres and scheduled lives are not eligible yet."},{"question":"Should YouTube titles include keywords?","answer":"Include the natural phrase people search for once, then stop. Keyword stuffing reads as spam to viewers and does not help modern search matching."},{"question":"Should the title repeat the thumbnail text?","answer":"No. The best YouTube titles and thumbnails work as two halves of one idea: the thumbnail shows the emotion or visual hook, and the title adds the context."},{"question":"Can Creator AI suggest YouTube titles?","answer":"Yes. Every video idea from Creator AI's ideation tool comes with several title variations and an opportunity score, which gives you candidates to test."}],"seo_title":"How to Write YouTube Titles That Get Clicks: 7 Proven Formulas (2026)","seo_description":"Write YouTube titles that earn the click and keep the viewer: length limits, 7 proven formulas, CTR-killing mistakes and built-in A/B tests.","focus_keyword":"youtube titles","published_at":"2026-09-13T12:00:00.000Z","branded_cta":{"title":"Get 10 video ideas for your niche","description":"Creator AI reads your channel and returns ten researched concepts with hooks and angles, compared side by side so you know which one to make first.","buttonLabel":"Find my next video","buttonHref":"/signup"},"videos":[]},{"slug":"open-vs-closed-captions-which-youtube-creators-should-use-2026","title":"Open vs Closed Captions: Stop Picking the Wrong One for YouTube","excerpt":"Burned-in or a caption file? What open and closed captions actually do on YouTube, Shorts and TikTok, and the hybrid setup most channels should use.","content":"\n> **Open vs closed captions: which should YouTube creators use?** Closed captions are a separate file (SRT or VTT) that viewers can switch on and off, and YouTube can read and auto-translate them. Open captions are burned into the video pixels and always visible. For long-form YouTube, upload closed captions. For Shorts, Reels and TikTok, where most people watch muted, burn in open captions, and ideally upload a closed caption file too.\n\n![Open vs closed captions: editing and exporting subtitles in Creator AI](/subtitle%20page.png)\n\nEvery creator who adds subtitles eventually hits the same fork. Do you upload a caption file, or do you burn the text into the video itself? The two look similar on screen, but they behave completely differently once the video is published.\n\nThis guide explains the open vs closed captions decision in plain terms: what each one is, where each one wins, and the hybrid setup most growing channels end up using.\n\n## What are open vs closed captions?\n\nThe W3C, which writes the web accessibility standards, defines the difference in its [WCAG guidance on captions](https://www.w3.org/WAI/WCAG22/Understanding/captions-prerecorded.html): closed captions can be turned on and off by the viewer, while open captions are always visible because they are part of the video image.\n\nIn practice:\n\n- **Closed captions (CC)** live in a text file with timestamps, usually SRT or VTT. The player draws them on top of the video. The viewer controls them.\n- **Open captions** are rendered into the video frames during export, often called \"burned-in\" or \"hardcoded\" subtitles. Nobody can turn them off, resize them, or translate them, because they are pixels, not text.\n\nIf you are unsure what an SRT or VTT file actually contains, our explainer on [SRT vs VTT subtitle formats](/blog/srt-vs-vtt-subtitle-formats-explained-2026) walks through both.\n\n## Open vs closed captions at a glance\n\n| | Closed captions | Open captions |\n|---|---|---|\n| Viewer can turn off | Yes | No |\n| Viewer can resize or restyle | Yes, in player settings | No |\n| Readable by YouTube as text | Yes | Not reliably, they are image pixels |\n| Auto-translation on YouTube | Yes | No |\n| Looks the same everywhere | No, each player styles them | Yes, exactly as designed |\n| Survives reposting to other apps | No, the file stays behind | Yes |\n| Can fix a typo after publishing | Yes, edit the file | No, you must re-export and re-upload |\n\n## When closed captions win\n\n### Long-form YouTube videos\n\nOn a standard YouTube upload, closed captions are the stronger default. The viewer who wants them turns them on; the viewer who does not keeps a clean frame. Viewers can also change the size, colour and background of closed captions in YouTube's caption settings, which matters for people with low vision.\n\n### Reaching viewers in other languages\n\nThis is the biggest practical difference in the open vs closed captions choice. When a video has a caption track, viewers can use YouTube's auto-translate option to read it in their own language. Burned-in text cannot be translated at all. If you have an international audience, open captions quietly lock them out.\n\nFor a deeper look at the growth side, see [how subtitles boost YouTube views and watch time](/blog/how-subtitles-boost-youtube-views-and-watch-time).\n\n### Search and discoverability\n\nA caption file gives YouTube a clean, accurate transcript of what you said. Burned-in text is part of the image, so you are relying on the platform to read pixels rather than handing it the words directly. YouTube also generates automatic captions, but they make mistakes on names, jargon and accents. Our guide to [YouTube auto captions accuracy](/blog/youtube-auto-captions-accuracy-how-to-fix-caption-errors-2026) covers why uploading your own corrected file beats relying on them.\n\n### Fixing mistakes\n\nSpot a typo in a closed caption file a week after publishing? Edit the file and re-upload it in YouTube Studio. The video, its views and its comments stay untouched. A typo in open captions is permanent unless you delete and re-upload the whole video.\n\n## When open captions win\n\n### Shorts, Reels and TikTok\n\nShort-form feeds autoplay, and a large share of viewers scroll with the sound off. Open captions are visible from the first frame without the viewer doing anything, which is exactly when you need to hold them. They are also part of the style of short-form video: big, bold, word-by-word text is a retention device, not just an accessibility feature.\n\n### Cross-posting one file everywhere\n\nIf you export one vertical video and post it to YouTube Shorts, Instagram and TikTok, burned-in captions travel with it. Closed caption files do not; each platform would need its own upload, and some handle them poorly.\n\n### Brand control\n\nOpen captions look exactly as you designed them: your font, your colours, your position. Closed captions are drawn by each player in its own style, which you do not control.\n\n## The downsides nobody mentions\n\nOpen captions have real costs:\n\n- **They can block the frame.** Burned-in text can collide with on-screen graphics, faces, or platform UI like the like and comment buttons on Shorts.\n- **They do not help every viewer equally.** A viewer who needs larger text cannot enlarge them.\n- **They can double up.** If you burn in captions *and* a viewer turns on YouTube's automatic captions, two sets of text stack on screen.\n\nClosed captions have costs too. They depend on the viewer turning them on, and many casual viewers never do. On muted autoplay feeds, that means a closed-caption-only Short can look like a silent video.\n\n## The hybrid setup most channels should use\n\nThe open vs closed captions question rarely needs a single answer. Most growing channels do both, split by format:\n\n1. **Long-form uploads:** closed captions only. Upload a corrected SRT or VTT file.\n2. **Shorts and vertical clips:** burn in open captions for the muted scroll, and upload a closed caption file as well so YouTube still gets the text and can translate it.\n3. **Keep the source file.** Always export and store the SRT alongside the video. It is the input for burned-in captions, translations and dubbing later.\n\nAccessibility-wise, the W3C guidance also notes that proper captions include more than dialogue: speaker changes and meaningful sounds like music or laughter. That applies to both types.\n\n## How to make both in Creator AI\n\nCreator AI's subtitle tool transcribes your video, lets you correct lines in an inline editor next to the video player, and style the text. From the same project you can export an SRT or VTT file for closed captions, or burn the styled subtitles directly into an MP4 for open captions. One transcript, both outputs, so you do not fix the same typo twice.\n\nIf transcription quality is your main concern, we tested tools side by side in our [accurate AI subtitle generator comparison](/blog/accurate-ai-subtitle-generator-for-youtube-tested-2026). And if you plan to go beyond subtitles into other languages entirely, see [how to dub YouTube videos into multiple languages](/blog/how-to-dub-youtube-videos-into-multiple-languages-ai).\n\n## Conclusion\n\nThe open vs closed captions choice comes down to where the video will be watched. Closed captions win on YouTube long-form: they are toggleable, translatable, editable and readable as text. Open captions win on muted short-form feeds and anywhere you cross-post one file.\n\nYou do not have to pick one forever. Keep a clean caption file for every video, burn it in for Shorts, upload it as closed captions everywhere YouTube accepts one, and you get the benefits of both.\n","category":"Subtitles","author_name":"Afrin Nahar","read_time":"8 min read","featured":false,"tags":["Subtitles","Accessibility","Shorts","YouTube"],"keywords":["burned in subtitles vs closed captions","hardcoded subtitles youtube","should i burn captions into shorts","open captions for tiktok and reels","closed captions auto translate youtube","difference between open and closed captions"],"faqs":[{"question":"What is the difference between open and closed captions?","answer":"Closed captions are a separate text file the viewer can turn on or off. Open captions are burned into the video image and are always visible."},{"question":"Are open or closed captions better for YouTube?","answer":"For long-form YouTube, closed captions are better: viewers can toggle and resize them, YouTube can auto-translate them, and you can fix typos after publishing."},{"question":"Should I burn captions into YouTube Shorts?","answer":"Usually yes, because many short-form viewers scroll muted. Upload a closed caption file as well so YouTube still gets the text and can translate it."},{"question":"Can YouTube translate burned-in captions?","answer":"No. Auto-translation works on caption tracks. Burned-in open captions are pixels in the video, so they stay in the original language."},{"question":"Can Creator AI make both open and closed captions?","answer":"Yes. Creator AI transcribes your video, lets you edit and style the subtitles, then exports SRT or VTT for closed captions or burns them into an MP4 for open captions."}],"seo_title":"Open vs Closed Captions: Best Choice for YouTube & Shorts (2026)","seo_description":"Open vs closed captions for YouTube: when to burn subtitles in, when to upload an SRT, and the hybrid setup that works for long-form and Shorts.","focus_keyword":"open vs closed captions","published_at":"2026-09-17T12:00:00.000Z","branded_cta":{"title":"Caption your next upload in minutes","description":"Creator AI transcribes the video, lets you fix any line in an editor, and exports a subtitle file YouTube can actually read for search.","buttonLabel":"Generate subtitles free","buttonHref":"/signup"},"videos":[]}]$blogseed$::jsonb) AS s(
  slug text, title text, excerpt text, content text, category text, author_name text,
  read_time text, featured boolean, tags text[], keywords text[], faqs jsonb, videos jsonb,
  seo_title text, seo_description text, focus_keyword text, branded_cta jsonb,
  published_at timestamptz
)
ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content,
  category = EXCLUDED.category, author_name = EXCLUDED.author_name, read_time = EXCLUDED.read_time,
  featured = EXCLUDED.featured, tags = EXCLUDED.tags, keywords = EXCLUDED.keywords,
  faqs = EXCLUDED.faqs, videos = EXCLUDED.videos, seo_title = EXCLUDED.seo_title,
  seo_description = EXCLUDED.seo_description, focus_keyword = EXCLUDED.focus_keyword,
  branded_cta = EXCLUDED.branded_cta, status = EXCLUDED.status,
  published_at = EXCLUDED.published_at, updated_at = now();
